// @lib box

import Matter from 'npm:matter-js' 

const { Body, Bodies, Composite, Vector } = Matter

// The Nature of Code
// Daniel Shiffman
// http://natureofcode.com

// A rectangular box

export class Box {
  constructor(x, y, engine) {
    this.w = random(8, 16);
    this.h = random(8, 16);
    this.engine = engine

    let options = { restitution: 0.6 };
    this.body = Bodies.rectangle(x, y, this.w, this.h, options);
    Body.setVelocity(this.body, Vector.create(random(-5, 5), 0));
    Body.setAngularVelocity(this.body, 0.1);
    Composite.add(this.engine.world, this.body);
  }

  // Drawing the box
  show() {
    if (!this.body) return

    let pos = this.body.position;
    let a = this.body.angle;

    rectMode(CENTER);
    fill('yellow');
    stroke(0);
    strokeWeight(2);
    push();
    translate(pos.x, pos.y);
    rotate(a);
    rect(0, 0, this.w, this.h);
    pop();
  }

  checkEdge() {
    if (!this.body) return

    return this.body.position.y > height + this.w;
  }

  // This function removes a body from the Matter.js world.
  removeBody() {
    if (!this.body) return

    Composite.remove(this.engine.world, this.body);
  }
}

import Matter from 'npm:matter-js' 

const { Engine, Bodies, Composite, Body, Vector } = Matter

// @lib boundary
// The Nature of Code
// Daniel Shiffman
// http://natureofcode.com

// A rectangular boundary

export class Boundary {
  constructor(x, y, w, h, engine) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.engine = engine

    let options = { isStatic: true };
    this.body = Bodies.rectangle(this.x, this.y, this.w, this.h, options);

    Composite.add(this.engine.world, this.body);
  }

  // Drawing the box
  show() {
    rectMode(CENTER);
    fill('white');
    stroke(0);
    strokeWeight(2);    
    rect(this.x, this.y, this.w, this.h);
  }
}

