import Matter from 'npm:matter-js'

const { Engine, Bodies, Composite, Body, Vector } = Matter

// A reference to the matter physics engine
let engine;

import { Box } from 'box'
import { Boundary } from 'boundary'

// An array for all boxes
let boxes = [];

// An array for all boundaries
let boundaries = [];

async function setup() {
  createCanvas(640, 240);
  noDrag()

  engine = Engine.create();

  // Add a bunch of fixed boundaries
  boundaries.push(new Boundary(width / 4, height - 5, width / 2 - 50, 10, engine));
  boundaries.push(
    new Boundary((3 * width) / 4, height - 50, width / 2 - 50, 10, engine)
  );

}

function draw() {
  clear()

  // Update the engine!
  Engine.update(engine);

  // Boxes fall from the top every so often
  if (random(1) < 0.1) {
    let b = new Box(width / 2, 50, engine);
    boxes.push(b);
  }

  // Iterate over the boxes backwards
  for (let i = boxes.length-1; i >= 0; i--) {
    boxes[i].show();
    // Remove the Body from the world and the array
    if (boxes[i].checkEdge()) {
      boxes[i].removeBody();
      boxes.splice(i, 1);
    }
  }
  // Display all the boundaries
  for (let i = 0; i < boundaries.length; i++) {
    boundaries[i].show();
  }
}
